import java.util.LinkedHashMap;
import java.util.Map;

public class FirstUniqueCharFinder {
    public static Character findFirstNonRepeating(String input) {
        if (input == null || input.isEmpty()) return null;

        // LinkedHashMap preserves character arrival order
        Map<Character, Integer> counts = new LinkedHashMap<>();

        // Pass 1: Build frequency histogram in O(N)
        for (char c : input.toCharArray()) {
            counts.merge(c, 1, Integer::sum);
        }

        // Pass 2: Traverse ordered map to find first key with count == 1 in O(U)
        for (Map.Entry<Character, Integer> entry : counts.entrySet()) {
            if (entry.getValue() == 1) {
                return entry.getKey();
            }
        }
        return null; // All characters repeated
    }

    public static void main(String[] args) {
        String test = "swiss";
        System.out.println("First non-repeating in 'swiss': " + findFirstNonRepeating(test)); // 'w'
    }
}

