import java.util.List;
import java.util.Map;
import java.util.HashMap;

public class DepartmentInverter {
    public static Map<String, String> invertDeptMap(Map<String, List<String>> deptMap) {
        Map<String, String> empToDept = new HashMap<>();
        if (deptMap != null) {
            for (Map.Entry<String, List<String>> entry : deptMap.entrySet()) {
                String dept = entry.getKey();
                List<String> emps = entry.getValue();
                if (emps != null) {
                    for (String emp : emps) {
                        empToDept.put(emp, dept);
                    }
                }
            }
        }
        return empToDept;
    }
}

