import java.util.List;
import java.util.Map;
import java.util.HashMap;

public class SpendingAggregator {
    public record Transaction(String category, double amount) {}

    public static Map<String, Double> aggregateTotals(List<Transaction> transactions) {
        Map<String, Double> totals = new HashMap<>();
        if (transactions != null) {
            for (Transaction t : transactions) {
                if (t != null && t.category() != null) {
                    totals.merge(t.category(), t.amount(), Double::sum);
                }
            }
        }
        return totals;
    }
}
